{"verbose_logs": "Verdicts:
[
    {
        "verdicts": [
            {
                "statement": "We are seeking a highly motivated Cloud Engineer to join our multi-million dollar National Intelligence program supporting the Cloud Investment Multi-Cloud Management (CIMM) program.",
                "verdict": "yes",
                "reason": null
            },
            {
                "statement": "As a Cloud Engineer, you will advise mission users on utilizing cloud-based IT systems, provide support for development in, or transition to the cloud, and be responsible for the implementation, troubleshooting, and maintenance of cloud environments.",
                "verdict": "yes",
                "reason": null
            },
            {
                "statement": "You will manage system infrastructure and any processes related to these systems.",
                "verdict": "yes",
                "reason": null
            }
        ]
    },
    {
        "verdicts": [
            {
                "statement": "Experience with cloud platforms such as AWS, Azure, or Google Cloud.",
                "verdict": "yes",
                "reason": null
            },
            {
                "statement": "Knowledge of monitoring and logging tools like Datadog, New Relic, Splunk, Prometheus, ELK Stack, or Grafana.",
                "verdict": "yes",
                "reason": null
            },
            {
                "statement": "Certification in DevOps or related field (e.g., AWS Certified DevOps Engineer, Docker Certified Associate).",
                "verdict": "yes",
                "reason": null
            }
        ]
    },
    {
        "verdicts": [
            {
                "statement": "As a DevOps/Cloud Engineer you will help harden software solutions supporting divisions going through a technological transformation, guide development teams through creating and automating their cloud infrastructure, and build and maintain the central platform and solutions for R&D teams.",
                "verdict": "yes",
                "reason": null
            },
            {
                "statement": "You should be well versed and have good practical experience in the following topics:",
                "verdict": "yes",
                "reason": null
            }
        ]
    },
    {
        "verdicts": [
            {
                "statement": "Applies software knowledge to assist and support the design, development, creation, modification, and validation of embedded and cloud edge software, applications, and/or specialized utility programs; analyzes user needs and software requirements; designs and implements small software features; participates in coding, unit testing, debugging, integration, code reviews, regression tests, and documentation; develops cloud-based applications and services, designs and implements unstructured cloud data (S3) I/O and processing, optimizes engineering data pipelines, and implements data security for product development and test engineering.",
                "verdict": "yes",
                "reason": null
            }
        ]
    },
    {
        "verdicts": [
            {
                "statement": "The Cloud Data Engineer will be responsible for designing and implementing analytics solutions as part of a team, functioning as a technical consultant and working with the client to facilitate project success.",
                "verdict": "yes",
                "reason": null
            },
            {
                "statement": "Qualifications include experience with Microsoft database and BI technologies, Azure Data Lake Storage, Azure SQL DW/Azure Synapse, Azure Data Factory, MPP architecture, PolyBase, T\u2011SQL development, data modeling, ETL strategies, data warehousing or big data solutions, rapid prototyping, plus Python, a BS/MS in Computer Science, strong communication, teamwork, and problem\u2011solving skills.",
                "verdict": "yes",
                "reason": null
            }
        ]
    }
]"}

